#pragma once

#include <QColor>
#include <QIcon>
#include <QString>

class QApplication;

namespace ads {
class CDockManager;
}

namespace usdcc::ui::theme {

// The usdcc app icon (three stacked blue layers), as a multi-size QIcon.
// apply() installs it as the application's window icon, which is what the
// title bar logo and the taskbar show while the app runs; the .exe's own
// icon (Explorer, pinned shortcuts) comes from src/cpp/app/resources/usdcc.ico.
// Both are generated by tools/gen_app_icon.py.
QIcon appIcon();

// The Appearance/accentColor setting (usdcc::core::Settings): the colour of
// selections, checked buttons, focus borders and links.
inline constexpr auto accentColorKey = "Appearance/accentColor";
inline constexpr auto defaultAccentColor = "#3d8bfd";

// Defines the theme's settings in Settings::instance() (apply() does this).
void defineSettings();

// The current accent colour (the default one if the setting is undefined).
QColor accent();

// `sheet` with the stylesheet tokens replaced: @accent-rgb by "r, g, b" (for
// rgba(@accent-rgb, 25%)), @accent-hover by a lighter shade and @accent by
// the colour itself.
QString resolveTokens(const QString& sheet, const QColor& accentColor);

// The application's dark theme (see docs/PLAN.md §6, "Dark theme"): the Fusion
// style with a dark palette, plus the app-wide stylesheet from
// resources/theme/dark.qss. Call once, right after constructing the
// QApplication and before creating any widgets. Follows UI scale and accent
// colour changes from then on.
void apply(QApplication& app);

// ADS gives its dock manager its own widget-level stylesheet, which beats
// the app-wide one for the properties it sets — so the tabs, title bars and
// splitter handles need a second pass. Appends resources/theme/dock.qss to
// the manager's existing stylesheet. Call right after constructing the
// manager.
void applyToDockManager(ads::CDockManager* dockManager);

}  // namespace usdcc::ui::theme
